// .agents/slop/browser/web/fchain-run.js -- RUN A SET OF PORT-RENDERED WGSL KERNELS ON WEBGPU.
//
// ONE EXECUTOR FOR BOTH LANES. `fchain-wgsl.html` feeds it modules that were rendered ahead of time;
// `fchain-wgsl-live.html` feeds it modules the PAGE just generated by running the port's own renderer
// (`fchainwgsl.mjs`, compiled by `./bin/bend ... -o`). The WebGPU code is not duplicated between them,
// because a lane that renders differently must not also dispatch differently.
//
// THE PAGE NEVER GRADES ITSELF: this reports the GPU's words and `fchain-wgsl-gate.mjs` diffs them
// against the C harness's `--dump`, which is served from OUTSIDE this directory.

const SIZES = { h1: 196, x: 784, w1: 4, h2: 196, h3: 49, out: 10, w2: 490 };

// `--w<N>` sections, one per kernel, exactly as `fchainwgsl.bend` prints them.
export const splitModules = (s) => s.split("--w").filter((p) => p.trim()).map((p) => p.slice(p.indexOf("\n") + 1));

export async function runStages({ modules, wiring, seed }, done) {
  const R = (o) => done(o);
  if (!navigator.gpu) return R({ ok: false, error: "navigator.gpu is absent" });
  const adapter = await navigator.gpu.requestAdapter();
  if (!adapter) return R({ ok: false, error: "no adapter" });
  const dev = await adapter.requestDevice();
  // EVERY uncaptured error is KEPT, in order: a later `[Invalid CommandBuffer]` is a CONSEQUENCE.
  const ERRS = [];
  dev.addEventListener("uncapturederror", (e) => ERRS.push(String(e.error.message)));

  const buf = {};
  for (const [n, sz] of Object.entries(SIZES)) {
    buf[n] = dev.createBuffer({ size: sz * 4, usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST });
  }
  for (const [n, words] of Object.entries(seed)) dev.queue.writeBuffer(buf[n], 0, new Uint32Array(words));
  // the INFINITY uniform every module declares at binding 0
  const inf = dev.createBuffer({ size: 4, usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST });
  dev.queue.writeBuffer(inf, 0, new Float32Array([Infinity]));

  for (let k = 0; k < modules.length; k++) {
    const mod = dev.createShaderModule({ code: modules[k] });
    const info = await mod.getCompilationInfo();
    const errs = info.messages.filter((m) => m.type === "error");
    if (errs.length) return R({ ok: false, error: "wgsl compile k" + k, messages: errs.map((m) => `${m.lineNum}:${m.linePos} ${m.message}`), errors: ERRS });
    // AN EXPLICIT LAYOUT, NOT "auto": `layout:"auto"` OMITS a binding the shader never reads, and k0
    // never touches `INFINITY` -- so the uniform entry is rejected and the bind group is invalid
    // (MEASURED: `[Invalid BindGroup]` at `submit k0`). This is the layout `runtime/ops_webgpu.bend`
    // documents: binding 0 Uniform, then one Storage per global, in order.
    const entries = [{ binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: "uniform" } }];
    wiring[k].forEach((_, i) => entries.push({ binding: i + 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } }));
    const bgl = dev.createBindGroupLayout({ entries });
    dev.pushErrorScope("validation");
    const pipe = dev.createComputePipeline({ layout: dev.createPipelineLayout({ bindGroupLayouts: [bgl] }), compute: { module: mod, entryPoint: "test" } });
    const perr = await dev.popErrorScope();
    if (perr) return R({ ok: false, error: "pipeline k" + k, messages: [perr.message], errors: ERRS });
    const bg = dev.createBindGroup({ layout: bgl, entries: [{ binding: 0, resource: { buffer: inf } },
      ...wiring[k].map((n, i) => ({ binding: i + 1, resource: { buffer: buf[n] } }))] });
    const enc = dev.createCommandEncoder();
    const pass = enc.beginComputePass();
    pass.setPipeline(pipe); pass.setBindGroup(0, bg); pass.dispatchWorkgroups(1, 1, 1);
    pass.end();
    dev.pushErrorScope("validation");
    dev.queue.submit([enc.finish()]);
    const serr = await dev.popErrorScope();
    if (serr) return R({ ok: false, error: "submit k" + k, messages: [serr.message], errors: ERRS });
  }

  const stages = {};
  for (const n of ["h1", "h2", "h3", "out"]) {
    const b = buf[n], rb = dev.createBuffer({ size: b.size, usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ });
    const enc = dev.createCommandEncoder();
    enc.copyBufferToBuffer(b, 0, rb, 0, b.size);
    dev.queue.submit([enc.finish()]);
    await rb.mapAsync(GPUMapMode.READ);
    stages[n] = Array.from(new Uint32Array(rb.getMappedRange().slice(0)));
    rb.unmap(); rb.destroy();
  }
  return R(ERRS.length ? { ok: false, error: "gpu errors", messages: ERRS, stages }
                       : { ok: true, adapter: adapter.info?.description ?? "adapter", stages });
}
